def indexed_generator(iterable, index):
    for item in iterable:
        if index == 0:
            yield item
        elif index == 1:
            yield item
        else:
            continue
if __name__ == '__main__':
    data = [10, 20, 30, 40, 50]
    print("Index 0:")
    for item in indexed_generator(data, 0):
        print(item)
    print("\nIndex 1:")
    for item in indexed_generator(data, 1):
        print(item)
    print("\nIndex 2:")
    for item in indexed_generator(data, 2):
        print(item)
    print("\nIndex 5 (out of bounds):")
    for item in indexed_generator(data, 5):
        print(item)

def indexed_generator(iterable, index):
    for i, item in enumerate(iterable):
        if i == index:
            yield item
if __name__ == '__main__':
    data = list(range(1000000))
    target_index = 500000
    generator = indexed_generator(data, target_index)
    result = list(generator)
    print(f"Found element at index {target_index}: {result[0]}")

def indexed_iterator(iterable, index):
    if not isinstance(iterable, (list, tuple)):
        raise TypeError("Input must be a list or tuple")
    try:
        if index < 0:
            return
        yield iterable[index]
    except IndexError:
        return
if __name__ == '__main__':
    data = list(range(1000000))
    print("Testing index 0:")
    for item in indexed_iterator(data, 0):
        print(item)
        if item == 1:
            break
    print("\nTesting index 500000:")
    for item in indexed_iterator(data, 500000):
        print(item)
        if item == 500000:
            break
    print("\nTesting out of bounds index (1000000):")
    for item in indexed_iterator(data, 1000000):
        print(item)
    print("\nTesting negative index (-1):")
    for item in indexed_iterator(data, -1):
        print(item)

