def calculate_differences(list1: list[float], list2: list[float]) -> list[float]:
    if len(list1) != len(list2):
        raise ValueError("Input lists must have the same length")
    differences = []
    for a, b in zip(list1, list2):
        differences.append(a - b)
    return differences
