import timeit
import random
class O1List:
    def __init__(self, data):
        self._data = list(data)
    def __getitem__(self, index):
        return self._data[index]
    def __len__(self):
        return len(self._data)
def benchmark(list_data, num_accesses):
    standard_list = list_data
    o1_list = O1List(list_data)
    time_standard = timeit.timeit(lambda: standard_list[random.randint(0, len(list_data) - 1)], number=num_accesses)
    time_o1 = timeit.timeit(lambda: o1_list[random.randint(0, len(list_data) - 1)], number=num_accesses)
    return time_standard, time_o1
if __name__ == '__main__':
    SAMPLE_SIZE = 1000000
    NUM_ITERATIONS = 100000
    sample_data = [random.randint(0, 1000000) for _ in range(SAMPLE_SIZE)]
    time_std, time_o1 = benchmark(sample_data, NUM_ITERATIONS)
    print(f"Sample Size: {SAMPLE_SIZE}")
    print(f"Number of Accesses per Test: {NUM_ITERATIONS}")
    print("-" * 30)
    print(f"Time taken for standard Python list access: {time_std:.6f} seconds")
    print(f"Time taken for O(1) custom structure access: {time_o1:.6f} seconds")
    print("-" * 30)
    if time_o1 < time_std:
        print("O(1) structure was faster.")
    elif time_o1 > time_std:
        print("Standard list was faster (unexpected for this benchmark).")
    else:
        print("Times were virtually identical.")

def get_first_last(iterable):
    try:
        return iterable[0], iterable[-1]
    except IndexError:
        return None, None
if __name__ == '__main__':
    list1 = [1, 2, 3, 4, 5]
    list2 = [10]
    list3 = []
    print(get_first_last(list1))
    print(get_first_last(list2))
    print(get_first_last(list3))

def get_first_and_last(sequence):
    if not sequence:
        raise IndexError("Cannot get first and last elements of an empty sequence.")
    first_element = sequence[0]
    last_element = sequence[-1]
