def middle_element_generator(iterable):
    n = len(iterable)
    if n == 0:
        return
    middle_index = n // 2
    for item in iterable:
        if middle_index == 0:
            yield item
        elif middle_index == n - 1:
            yield item
        else:
            if middle_index == 1:
                yield item
            elif middle_index == n - 2:
                yield item
            else:
                yield item
