def find_middle(data):
    n = len(data)
    if n == 0:
        return None
    else:
        middle_index = n // 2
        if n % 2 == 1:
            return data[middle_index]
        else:
            return data[middle_index - 1]
if __name__ == '__main__':
    list_odd = [1, 2, 3, 4, 5]
    list_even = [10, 20, 30, 40]
    list_single = [99]
    list_empty = []
    print(f"Middle of {list_odd}: {find_middle(list_odd)}")
    print(f"Middle of {list_even}: {find_middle(list_even)}")
    print(f"Middle of {list_single}: {find_middle(list_single)}")
    print(f"Middle of {list_empty}: {find_middle(list_empty)}")

def find_middle(data):
    n = len(data)
    if n == 0:
        return None
    else:
        middle_index = n // 2
        if n % 2 == 1:
            return data[middle_index]
        else:
            return (data[middle_index - 1] + data[middle_index]) // 2
if __name__ == '__main__':
    list_odd = [1, 2, 3, 4, 5]
    list_even = [10, 20, 30, 40]
    list_single = [99]
    list_empty = []
    print(f"Middle of {list_odd}: {find_middle(list_odd)}")
    print(f"Middle of {list_even}: {find_middle(list_even)}")
    print(f"Middle of {list_single}: {find_middle(list_single)}")
    print(f"Middle of {list_empty}: {find_middle(list_empty)}")

def compare_elements(list1, list2, index):
    try:
        element1 = list1[index]
    except IndexError:
        element1 = "Index out of bounds for list1"
    try:
        element2 = list2[index]
    except IndexError:
        element2 = "Index out of bounds for list2"
    return element1, element2
