class ListComparator:
    def compare_at_index(self, list1, list2, index):
        if index < 0 or index >= len(list1) or index >= len(list2):
            return {"error": "Index out of bounds"}
        val1 = list1[index]
        val2 = list2[index]
        if val1 < val2:
