def compare_elements_at_indices(lists, indices):
    results = {}
    for i in indices:
        if i < 0:
            raise ValueError("Indices must be non-negative")
        if len(lists) == 0:
            results[i] = None
            continue
        values = []
        valid_index = True
        for lst in lists:
            if i < len(lst):
                values.append(lst[i])
            else:
                values.append(None)
        results[i] = values
    return results
