def compare_elements(data, index1, index2):
    if not (0 <= index1 < len(data) and 0 <= index2 < len(data)):
        raise IndexError("Index out of bounds")
    val1 = data[index1]
    val2 = data[index2]
    if val1 > val2:
        return 'greater than'
    elif val1 < val2:
        return 'less than'
    else:
        return 'equal'
