import datetime
def date_difference_days(date1: datetime.date, date2: datetime.date) -> int:
    if date1 > date2:
        return date1.toordinal() - date2.toordinal()
    else:
        return date2.toordinal() - date1.toordinal()
if __name__ == '__main__':
    d1 = datetime.date(2023, 1, 1)
    d2 = datetime.date(2023, 1, 10)
    result1 = date_difference_days(d1, d2)
    print(result1)
    d3 = datetime.date(2024, 5, 20)
    d4 = datetime.date(2024, 3, 15)
    result2 = date_difference_days(d3, d4)
    print(result2)

from datetime import datetime
def date_difference(date_str1, date_str2):
    date1 = datetime.strptime(date_str1, '%Y-%m-%d')
    date2 = datetime.strptime(date_str2, '%Y-%m-%d')
    diff = date2 - date1
    years = diff.days // 365
    remaining_days = diff.days % 365
    months = remaining_days // 30
    remaining_days = remaining_days % 30
    days = diff.days % 30
    parts = []
    if years > 0:
        parts.append(f"{years} years")
    if months > 0:
        parts.append(f"{months} months")
    if days > 0:
        if len(parts) == 0:
            parts.append(f"{days} days")
        else:
            parts.append(f"{days} days")
    if not parts:
        return "0 days"
    if len(parts) == 1:
        return parts[0]
    elif len(parts) == 2:
        return f"{parts[0]} and {parts[1]}"
    else:
        return ", ".join(parts[:-1]) + f", and {parts[-1]}"
if __name__ == '__main__':
    date1 = "2023-01-15"
    date2 = "2024-05-20"
    result = date_difference(date1, date2)
    print(result)

import datetime
def calculate_days_between(date1_str, date2_str):
    try:
        date1 = datetime.datetime.strptime(date1_str, '%Y-%m-%d').date()
        date2 = datetime.datetime.strptime(date2_str, '%Y-%m-%d').date()
        if date1 > date2:
            difference = abs(date1 - date2)
        else:
            difference = date2 - date1
        return difference.days
    except ValueError:
        return "Error: Invalid date format. Please use YYYY-MM-DD."
    except TypeError:
        return "Error: One or both inputs were not valid date strings."
if __name__ == '__main__':
    date1_input = "2023-01-15"
    date2_input = "2023-03-20"
    result = calculate_days_between(date1_input, date2_input)
    print(result)

