class DateCalculator:
    def get_next_month_date(self, date_string):
        from datetime import datetime, timedelta
        date_obj = datetime.strptime(date_string, "%Y-%m-%d")
        if date_obj.month == 12:
            next_month = date_obj.replace(year=date_obj.year + 1, month=1, day=1)
        else:
            next_month = date_obj.replace(month=date_obj.month + 1, day=date_obj.day)
        return next_month.strftime("%Y-%m-%d")
if __name__ == '__main__':
    calculator = DateCalculator()
    sample_date = "2023-10-15"
    next_date = calculator.get_next_month_date(sample_date)
    print(f"The date after {sample_date} is {next_date}")
    sample_date_dec = "2023-12-31"
    next_date_dec = calculator.get_next_month_date(sample_date_dec)
    print(f"The date after {sample_date_dec} is {next_date_dec}")
    sample_date_jan = "2024-01-05"
    next_date_jan = calculator.get_next_month_date(sample_date_jan)
    print(f"The date after {sample_date_jan} is {next_date_jan}")

import unittest
from datetime import date
import calendar
def get_next_month(year, month):
    if month == 12:
        next_month = 1
        next_year = year + 1
    else:
        next_month = month + 1
        next_year = year
    return date(next_year, next_month)
class TestNextMonth(unittest.TestCase):
    def test_normal_month_transition(self):
        self.assertEqual(get_next_month(2023, 1), date(2023, 2))
        self.assertEqual(get_next_month(2023, 3), date(2023, 4))
        self.assertEqual(get_next_month(2023, 10), date(2023, 11))
    def test_year_boundary(self):
        self.assertEqual(get_next_month(2023, 12), date(2024, 1))
    def test_different_years(self):
        self.assertEqual(get_next_month(2022, 11), date(2022, 12))
        self.assertEqual(get_next_month(2024, 1), date(2024, 2))
    def test_leap_year_boundary(self):
        self.assertEqual(get_next_month(2024, 12), date(2025, 1))
if __name__ == '__main__':
    unittest.main(argv=['first-arg-is-ignored'], exit=False)

import unittest
from datetime import date
from dateutil.relativedelta import relativedelta
def get_next_month(target_date):
    next_month = target_date + relativedelta(months=1)
    return next_month.date()
class TestNextMonth(unittest.TestCase):
    def test_standard_month_transition(self):
        test_date = date(2023, 10, 15)
        expected_date = date(2023, 11, 15)
        self.assertEqual(get_next_month(test_date), expected_date)
    def test_year_boundary(self):
        test_date = date(2023, 12, 31)
        expected_date = date(2024, 1, 31)
        self.assertEqual(get_next_month(test_date), expected_date)
    def test_month_end_transition(self):
        test_date = date(2023, 1, 31)
        expected_date = date(2023, 2, 28)
        self.assertEqual(get_next_month(test_date), expected_date)
    def test_non_leap_year_february_end(self):
        test_date = date(2023, 2, 28)
        expected_date = date(2023, 3, 28)
        self.assertEqual(get_next_month(test_date), expected_date)
    def test_leap_year_february_end(self):
        test_date = date(2024, 2, 29)
        expected_date = date(2024, 3, 29)
        self.assertEqual(get_next_month(test_date), expected_date)
    def test_start_of_month(self):
        test_date = date(2023, 5, 1)
        expected_date = date(2023, 6, 1)
        self.assertEqual(get_next_month(test_date), expected_date)
if __name__ == '__main__':
    unittest.main(argv=['first-arg-is-ignored'], exit=False)

