        date2_str = date2_input
        date1 = datetime.strptime(date1_str, '%Y-%m-%d')
        date2 = datetime.strptime(date2_str, '%Y-%m-%d')
        if date1 < date2:
            ordered_date1 = date1
            ordered_date2 = date2
        else:
            ordered_date1 = date2
            ordered_date2 = date1
