from datetime import date
class DayOfYearCalculator:
    def calculate_day_of_year(self, year, month, day):
        if month == 2:
            if self._is_leap(year):
                return day
            else:
                return 28 + day
        else:
            day_of_year = 31 * (month - 1) + day
            return day_of_year
