            else:
                assert False, f"Unexpected error for {expression}: {e}"
        print("-" * 20)

import re
def evaluate_simple_expression(expression):
    match = re.match(r"(\d+)\s*([+\-*/])\s*(\d+)", expression)
    if not match:
        raise ValueError("Invalid expression format")
    num1 = int(match.group(1))
    operator = match.group(2)
    num2 = int(match.group(3))
    if operator == '+':
        return num1 + num2
    elif operator == '-':
        return num1 - num2
    elif operator == '*':
        return num1 * num2
    elif operator == '/':
        if num2 == 0:
            raise ZeroDivisionError("Division by zero")
        return num1 // num2
    else:
        raise ValueError("Unsupported operator")
if __name__ == '__main__':
    test_cases = [
        ("10 + 5", 15),
        ("20 - 8", 12),
        ("6 * 7", 42),
        ("100 / 4", 25),
        ("15 - 3", 12),
        ("5 * 10", 50),
        ("100 / 0", "Error")                               
    ]
    for expression, expected in test_cases:
        try:
            result = evaluate_simple_expression(expression)
            print(f"Expression: '{expression}', Result: {result}, Expected: {expected}")
            assert result == expected
        except Exception as e:
            print(f"Expression: '{expression}', Error: {e}")
            if expression == "100 / 0":
                if "ZeroDivisionError" in str(e):
                    print("Test passed for expected error.")
                else:
                    print("Test failed: Expected ZeroDivisionError but got something else.")
            else:
                print(f"Test failed unexpectedly: {e}")

def evaluate(num1, num2, operator):
    if operator == '+':
        return num1 + num2
    elif operator == '-':
        return num1 - num2
    elif operator == '*':
        return num1 * num2
    elif operator == '/':
        if num2 != 0:
            return num1 / num2
        else:
            raise ZeroDivisionError("Cannot divide by zero")
    elif operator == '%':
        if num2 != 0:
            return num1 % num2
        else:
            raise ZeroDivisionError("Cannot perform modulo by zero")
    else:
        raise ValueError(f"Unsupported operator: {operator}")
