def evaluate_binary_op(a, b, op):
    if op == '+':
        return a + b
    elif op == '-':
        return a - b
    elif op == '*':
        return a * b
    elif op == '/':
        if b == 0:
            raise ValueError("Division by zero")
        return a / b
    else:
        raise ValueError("Unsupported operation")
if __name__ == '__main__':
    print(evaluate_binary_op(10, 5, '+'))
    print(evaluate_binary_op(10, 5, '-'))
    print(evaluate_binary_op(10, 5, '*'))
    print(evaluate_binary_op(10, 5, '/'))
    try:
        evaluate_binary_op(10, 0, '/')
    except ValueError as e:
        print(f"Error caught: {e}")
    try:
        evaluate_binary_op(10, 5, '%')
    except ValueError as e:
        print(f"Error caught: {e}")

def calculator(num1, num2, symbol):
    operations = {
        '+': lambda a, b: a + b,
        '-': lambda a, b: a - b,
        '*': lambda a, b: a * b,
        '/': lambda a, b: a / b
    }
    if symbol in operations:
        return operations[symbol](num1, num2)
    else:
        raise ValueError(f"Unsupported operation: {symbol}")
def main():
    num1 = 20
    num2 = 5
    symbol = '*'
    try:
        result = calculator(num1, num2, symbol)
        print(f"Result of {num1} {symbol} {num2} is: {result}")
    except ValueError as e:
        print(f"Error: {e}")
if __name__ == '__main__':
    main()

