    def check_complex_condition(self, nested_states: dict) -> bool:
        def evaluate(state):
            if isinstance(state, bool):
                return state
            elif isinstance(state, dict):
                if not state:
                    return False
                return all(evaluate(value) for value in state.values())
            else:
                return bool(state)
        return evaluate(nested_states)
