def generate_truth_table(num_variables):
    num_rows = 2 ** num_variables
    truth_table = []
    for i in range(num_rows):
        row = []
        for j in range(num_variables):
            if (i >> j) & 1:
                row.append('T')
            else:
                row.append('F')
        truth_table.append(row)
    return truth_table
