    truth_table_data = generate_truth_table(num_vars)
    print(f"Truth Table for {num_vars} variables:")
    header = " | ".join([f"V{i+1}" for i in range(num_vars)])
    print("-" * len(header))
    print(header)
    print("-" * len(header))
    for row in truth_table_data:
        print(" | ".join(row))

