    ]
    print("--- Evaluating Expressions with Python's Operator Precedence ---")
    for expr in sample_expressions:
        print(f"\nExpression: {expr}")
        try:
            result = eval(expr)
            print(f"Result: {result}")
        except Exception as e:
            print(f"Evaluation Error: {e}")
        print("---")

