    results = []
    for i in range(0, len(tokens), 2):
        op = tokens[i]
        try:
            left = values[i]
            right = values[i+1]
            if op in precedence:
                if op == '==':
                    result = (left == right)
                elif op == '!=':
                    result = (left != right)
                elif op == '>':
                    result = (left > right)
                elif op == '<':
                    result = (left < right)
                elif op == '>=':
                    result = (left >= right)
                elif op == '<=':
                    result = (left <= right)
                elif op == '&&':
                    result = (left and right)
                elif op == '||':
                    result = (left or right)
                results.append(result)
            else:
                raise ValueError(f"Unknown operator: {op}")
        except IndexError:
            raise ValueError("Malformed expression: missing operands")
        except TypeError:
            raise ValueError(f"Type error during evaluation: {op} {left} {right}")
    return results
