    precedence_map = {
        '(': 0,
        ')': 0,
        '==': 1,
        '!=': 1,
        '>': 2,
        '<': 2,
        '+': 3,
        '-': 3,
        '*': 4,
        '/': 4,
        'and': 5,
        'or': 6
    }
    return precedence_map
def evaluate_expression(expression, precedence_map):
    tokens = expression.split()
    result_stack = []
    operator_stack = []
    def apply_op(op, values):
        if len(values) < 2:
            raise ValueError("Syntax error: insufficient operands")
        op2 = values.pop()
        op1 = values.pop()
        if op in precedence_map:
            result = None
            if op == '+':
                result = op1 + op2
            elif op == '-':
                result = op1 - op2
            elif op == '*':
                result = op1 * op2
            elif op == '/':
                result = op1 / op2
            elif op == '==':
                result = 1 if op1 == op2 else 0
            elif op == '!=':
                result = 1 if op1 != op2 else 0
            elif op == '>':
                result = 1 if op1 > op2 else 0
            elif op == '<':
                result = 1 if op1 < op2 else 0
            elif op == 'and':
                result = 1 if op1 and op2 else 0
            elif op == 'or':
                result = 1 if op1 or op2 else 0
            else:
                raise ValueError(f"Unknown operator: {op}")
            values.append(result)
            return
        else:
            raise ValueError(f"Unknown operator: {op}")
    for token in tokens:
        if token.isdigit() or (token.startswith('-') and token[1:].isdigit()):
            values = [float(token)]
        elif token == '(':
            operator_stack.append(token)
        elif token == ')':
            while operator_stack and operator_stack[-1] != '(':
                apply_op(operator_stack.pop(), values)
            if not operator_stack or operator_stack[-1] != '(':
                raise ValueError("Mismatched parentheses")
            operator_stack.pop()
        elif token in precedence_map:
            while (operator_stack and operator_stack[-1] != '(' and
                   precedence_map.get(operator_stack[-1], 0) >= precedence_map[token]):
                apply_op(operator_stack.pop(), values)
            operator_stack.append(token)
        else:
            raise ValueError(f"Invalid token: {token}")
    while operator_stack:
        if operator_stack[-1] == '(':
            raise ValueError("Mismatched parentheses")
        apply_op(operator_stack.pop(), values)
    if len(values) != 1:
        raise ValueError("Invalid expression structure")
    return values[0]
