import re
class BooleanEvaluator:
    def check_precedence(self, expression_string):
        tokens = re.findall(r'\(|\)|\bAND\b|\bOR\b|\bNOT\b|\d+|\+|\-|\(|\)|\,|\s+', expression_string)
        if not tokens:
            return "Error: Empty expression"
        tokens_processed = []
        for token in tokens:
            if token.strip() == "":
                continue
            tokens_processed.append(token)
        if not tokens_processed:
            return "Error: Could not parse expression"
        precedence_map = {
            'NOT': 3,
            'AND': 2,
            'OR': 1,
            '(': 0,
            ')': 0
        }
        evaluation_order = []
        for i, token in enumerate(tokens_processed):
            if token in precedence_map:
                evaluation_order.append((token, precedence_map[token], i))
            else:
                evaluation_order.append((token, 0, i))
        result = []
        for token, prec, index in evaluation_order:
            if token in ('AND', 'OR', 'NOT'):
                result.append({
                    'type': 'operator',
                    'token': token,
                    'precedence': prec,
                    'index': index
                })
            else:
                result.append({
                    'type': 'operand',
                    'token': token,
                    'precedence': 0,
                    'index': index
                })
        return result
if __name__ == '__main__':
    evaluator = BooleanEvaluator()
    test_cases = [
        "A AND B OR C",
        "(A AND B) OR C",
        "NOT A OR B",
        "A AND (B OR C)",
        "A OR B AND C",
        "NOT (A AND B)"
    ]
    for i, expr in enumerate(test_cases):
        print(f"--- Test Case {i+1}: {expr} ---")
        result = evaluator.check_precedence(expr)
        for item in result:
            print(f"Token: {item['token']}, Type: {item['type']}, Precedence: {item['precedence']}, Index: {item['index']}")
        print("-" * 30)
    print("\n--- Complex Scenario Test ---")
    complex_expr = "NOT A AND (B OR NOT C) OR D"
    result = evaluator.check_precedence(complex_expr)
    for item in result:
        print(f"Token: {item['token']}, Type: {item['type']}, Precedence: {item['precedence']}, Index: {item['index']}")
    print("-" * 30)

import re
class BooleanEvaluator:
    def check_precedence(self, expression_string):
        tokens = re.findall(r'\(|\)|\+|\-|\*|\/|\btrue\b|\bfalse\b|\bAND\b|\bOR\b|\bNOT\b|\b\d+\.\d+|\d+', expression_string)
        if not tokens:
            return "Error: Empty expression"
        output_order = []
        operator_stack = []
        precedence = {
            'NOT': 3,
            'AND': 2,
            'OR': 1,
            '(': 0,
            ')': 0
        }
        for token in tokens:
            if token.replace('.', '', 1).isdigit() or token in ('true', 'false'):
                output_order.append(token)
            elif token in precedence:
                operator_stack.append(token)
            elif token == '(':
                operator_stack.append(token)
            elif token == ')':
                while operator_stack and operator_stack[-1] != '(':
                    output_order.append(operator_stack.pop())
                if operator_stack and operator_stack[-1] == '(':
                    operator_stack.pop()
            elif token in ('AND', 'OR', '*', '/'):
                while (operator_stack and operator_stack[-1] != '(' and 
                       precedence.get(operator_stack[-1], 0) >= precedence[token]):
                    output_order.append(operator_stack.pop())
                operator_stack.append(token)
            elif token == 'NOT':
                operator_stack.append(token)
        while operator_stack:
            output_order.append(operator_stack.pop())
        return output_order
if __name__ == '__main__':
    evaluator = BooleanEvaluator()
    test_cases = [
        ("true AND false OR true", ["true", "false", "true", "AND", "OR"]),
        ("(true OR false) AND true", ["(", "true", "OR", "false", ")", "AND", "true"]),
        ("NOT true OR false", ["NOT", "true", "OR", "false"]),
        ("true AND (false OR true)", ["true", "AND", "(", "false", "OR", "true", ")"]),
        ("true OR false AND true", ["true", "OR", "false", "AND", "true"]),
        ("true AND true AND true", ["true", "AND", "true", "AND", "true"]),
        ("NOT (true AND false)", ["NOT", "(", "true", "AND", "false", ")"])
    ]
    for expression, expected_structure in test_cases:
        result = evaluator.check_precedence(expression)
        print(f"Expression: '{expression}'")
        print(f"Evaluation Order (Tokens/Operators): {result}")
        print("-" * 20)

import re
class BooleanEvaluator:
    def check_precedence(self, expression_string):
        tokens = re.findall(r'\(|\)|\+|\-|\*|\/|\btrue\b|\bfalse\b|\bAND\b|\bOR\b|\bNOT\b|\b\d+\.\d+|\d+', expression_string.replace(' ', ''))
        if not tokens:
            return "Error: Empty expression"
        processed_expression = expression_string
        processed_expression = processed_expression.replace('AND', 'and').replace('OR', 'or').replace('NOT', 'not')
        try:
            result = eval(processed_expression, {"__builtins__": None}, {})
            evaluation_order = []
            if 'not' in processed_expression:
                evaluation_order.append("NOT (Highest Precedence)")
            if 'and' in processed_expression:
                evaluation_order.append("AND (Medium Precedence)")
            if 'or' in processed_expression:
                evaluation_order.append("OR (Lowest Precedence)")
            if '(' in processed_expression or ')' in processed_expression:
                evaluation_order.append("Grouping (Parentheses dictate order)")
            if not evaluation_order:
                evaluation_order.append("Simple evaluation (no complex operators)")
            return "Evaluation Order: " + " -> ".join(evaluation_order)
        except Exception as e:
            return f"Error during evaluation: {e}"
if __name__ == '__main__':
