    test_cases = [
        ("true OR false", "Test 1: Simple OR"),
        ("(true OR false) AND true", "Test 2: Parentheses override"),
        ("true AND false OR true", "Test 3: AND before OR"),
        ("true OR true OR true", "Test 4: Left-to-right OR"),
        ("NOT true AND false", "Test 5: NOT precedence"),
        ("true AND (false OR true)", "Test 6: Nested precedence"),
        ("true OR false AND true", "Test 7: AND before OR"),
        ("true AND true AND true", "Test 8: Sequential AND"),
        ("false OR (true AND false)", "Test 9: Complex nesting")
    ]
    for expression, description in test_cases:
        result = evaluator.check_precedence(expression)
        print(f"--- {description} ---")
        print(f"Expression: {expression}")
        print(f"Result: {result}\n")

import re
class BooleanEvaluator:
    def check_precedence(self, expression_string):
        tokens = re.findall(r'\(|\)|\+|\-|\*|\/|\btrue\b|\bfalse\b|\bAND\b|\bOR\b|\bNOT\b|\b\d+\.\d+|\d+', expression_string.replace(' ', ''))
        if not tokens:
            return "Error: Empty expression"
        precedence_map = {
            'NOT': 3,
            'AND': 2,
            'OR': 1,
            '(': 0,
            ')': 0
        }
        output_queue = []
        operator_stack = []
        precedence = {'NOT': 3, 'AND': 2, 'OR': 1}
        for token in tokens:
            if token in ('true', 'false'):
                output_queue.append(token)
            elif token == '(':
                operator_stack.append(token)
            elif token == ')':
                while operator_stack and operator_stack[-1] != '(':
                    output_queue.append(operator_stack.pop())
                if operator_stack and operator_stack[-1] == '(':
                    operator_stack.pop()
            elif token in precedence:
                while (operator_stack and operator_stack[-1] != '(' and 
                       precedence.get(operator_stack[-1], 0) >= precedence[token]):
                    output_queue.append(operator_stack.pop())
                operator_stack.append(token)
            else:
                if token in ('AND', 'OR'):
                    operator_stack.append(token)
        while operator_stack:
            output_queue.append(operator_stack.pop())
        return "Evaluation Order Simulated: " + " -> ".join(output_queue)
if __name__ == '__main__':
    evaluator = BooleanEvaluator()
    expr1 = "true OR false AND true"
    result1 = evaluator.check_precedence(expr1)
    print(f"Expression: {expr1}")
    print(f"Result: {result1}\n")
    expr2 = "(true OR false) AND true"
    result2 = evaluator.check_precedence(expr2)
    print(f"Expression: {expr2}")
    print(f"Result: {result2}\n")
    expr3 = "NOT true AND (false OR NOT false)"
    result3 = evaluator.check_precedence(expr3)
    print(f"Expression: {expr3}")
    print(f"Result: {result3}\n")
    expr4 = "true OR false OR true AND false"
    result4 = evaluator.check_precedence(expr4)
    print(f"Expression: {expr4}")
    print(f"Result: {result4}\n")
    expr5 = "NOT (true AND false) OR (true OR false)"
    result5 = evaluator.check_precedence(expr5)
    print(f"Expression: {expr5}")
    print(f"Result: {result5}\n")

import ast
import operator
def evaluate_boolean_expression(expression, variables):
    node_map = {
        ast.And: operator.and_,
        ast.Or: operator.or_,
        ast.Not: operator.not_,
        ast.Eq: operator.eq,
        ast.NotEq: operator.ne,
        ast.Gt: operator.gt,
        ast.Lt: operator.lt,
        ast.GtE: operator.ge,
        ast.LtE: operator.le,
    }
    def _eval_node(node):
        if isinstance(node, ast.Expression):
            return _eval_node(node.body)
        elif isinstance(node, ast.Constant):
            if isinstance(node.value, bool):
                return node.value
            elif isinstance(node.value, (int, float)):
                return variables.get(node.value, 0)
            else:
                raise TypeError(f"Unsupported constant type: {type(node.value)}")
        elif isinstance(node, ast.Name):
            if node.id in variables:
                return variables[node.id]
            else:
                raise NameError(f"Variable '{node.id}' not defined")
        elif isinstance(node, ast.BoolOp):
            op = node.op
            if isinstance(op, ast.And):
                results = [_eval_node(n) for n in node.values]
                return operator.and_(*results)
            elif isinstance(op, ast.Or):
                results = [_eval_node(n) for n in node.values]
                return operator.or_(*results)
        elif isinstance(node, ast.UnaryOp):
            op = node.op
            operand = _eval_node(node.operand)
            if op == ast.Not:
                return operator.not_(operand)
        elif isinstance(node, ast.Compare):
            left = _eval_node(node.left)
            op_type = None
            right = _eval_node(node.comparators[0])
            if len(node.comparators) == 1:
                op_type = type(node.ops[0])
                if op_type in node_map:
                    op_func = node_map[op_type]
                    return op_func(left, right)
            raise ValueError("Complex comparison structure not fully supported in this simplified evaluator.")
        else:
            raise TypeError(f"Unsupported AST node type: {type(node)}")
    try:
        body = ast.parse(expression, mode='eval')
        result = _eval_node(body.body)
        return result
    except (SyntaxError, TypeError, NameError, ValueError) as e:
        return f"Error: {e}"
if __name__ == '__main__':
    variables = {
        "A": True,
        "B": False,
        "C": 10,
        "D": 5,
        "E": 20
    }
    expressions = [
        "A and not B",
