import ast
import operator
def evaluate_boolean_expression(expression, context=None):
    if context is None:
        context = {}
    class Context:
        def __init__(self, context):
            self.context = context
    class ExpressionEvaluator(ast.NodeVisitor):
        def visit_Expression(self, node):
            if isinstance(node, ast.BoolOp):
                op = node.op
                values = [self.visit(v) for v in node.values]
                if op == "and":
                    return all(values)
                elif op == "or":
                    return any(values)
            elif isinstance(node, ast.UnaryOp):
                op = node.op
                operand = self.visit(node.operand)
                if op == "not":
                    return not operand
            elif isinstance(node, ast.Compare):
                left = self.visit(node.left)
                op = None
                right = self.visit(node.comparators[0])
                if len(node.comparators) == 1:
                    op = type(node.comparators[0])
                    right = node.comparators[0]
                elif len(node.comparators) > 1:
                    op = type(node.comparators[0])
                    right = node.comparators[0]
                if op is not None:
                    try:
                        result = operator.gt(left, right) if op == ast.Gt else \
                                  operator.lt(left, right) if op == ast.Lt else \
                                  operator.eq(left, right) if op == ast.Eq else \
                                  operator.ge(left, right) if op == ast.Ge else \
                                  operator.le(left, right) if op == ast.Le else \
                                  None
                        return bool(result)
                    except TypeError:
                        return False
                return False
            return None
    try:
        tree = ast.parse(expression, mode='eval')
        evaluator = ExpressionEvaluator()
        result = evaluator.visit(tree.body)
        return bool(result)
    except SyntaxError:
        return "Syntax Error"
    except Exception:
        return "Evaluation Error"
