class LogicChecker:
    def evaluate_expression(self, expression: str, variables: dict) -> bool:
        import re
        def evaluate_token(token, vars):
            if token.isdigit() or (token.startswith('-') and token[1:].isdigit()):
                return float(token)
            return vars.get(token, 0)
        tokens = re.findall(r'[a-zA-Z_()]|[-+*/=]|[\d.]+', expression)
        if not tokens:
            raise ValueError("Empty expression")
        stack = []
        operators = []
        for token in tokens:
            if token.replace('.', '', 1).isdigit():
                stack.append(float(token))
            elif token in ['(', '+', '-', '*', '/', '=']:
                if token in ['+', '-', '*', '/']:
                    operators.append(token)
                elif token == '(':
                    stack.append(token)
                elif token == '=':
                    if len(stack) < 2:
                        raise ValueError("Syntax error: '=' requires two operands")
                    op = operators.pop()
                    right = stack.pop()
                    left = stack.pop()
                    if op == '+':
                        result = left + right
                    elif op == '-':
                        result = left - right
                    elif op == '*':
                        result = left * right
                    elif op == '/':
                        if right == 0:
                            raise ZeroDivisionError("Division by zero")
                        result = left / right
                    stack.append(result)
                else:
                    pass
            else:
                if token in variables:
                    stack.append(variables[token])
                else:
                    raise NameError(f"Undefined variable: {token}")
        if not stack:
            raise ValueError("Invalid expression structure")
        if len(stack) != 1:
            raise ValueError("Invalid expression structure or unmatched operators")
        result = stack[0]
        if isinstance(result, (int, float)):
            return bool(result)
        return bool(result)
