        (1, 1),                                                      
        (15, 3),                       
        (29, 2),                                                                    
        (31, 12)                      
    ]
    for day, month in test_cases:
        result = calculate_day_of_week(day, month)
        print(f"Day: {day}, Month: {month} -> Day of the week: {result}")

