import datetime
class TimeCalculator:
    def __init__(self, base_time=None):
        self.base_time = base_time if base_time is not None else datetime.datetime.now()
    def add_time(self, delta, unit='seconds'):
        if unit == 'seconds':
            if isinstance(delta, (int, float)):
                new_time = self.base_time + datetime.timedelta(seconds=delta)
                return new_time
            else:
                raise TypeError("Delta for seconds must be a number.")
        elif unit == 'minutes':
            if isinstance(delta, (int, float)):
                new_time = self.base_time + datetime.timedelta(minutes=delta)
                return new_time
            else:
                raise TypeError("Delta for minutes must be a number.")
        elif unit == 'hours':
            if isinstance(delta, (int, float)):
                new_time = self.base_time + datetime.timedelta(hours=delta)
                return new_time
            else:
                raise TypeError("Delta for hours must be a number.")
        else:
            raise ValueError("Unsupported time unit. Use 'seconds', 'minutes', or 'hours'.")
    def subtract_time(self, delta, unit='seconds'):
        if unit == 'seconds':
            if isinstance(delta, (int, float)):
                new_time = self.base_time - datetime.timedelta(seconds=delta)
                return new_time
            else:
                raise TypeError("Delta for seconds must be a number.")
        elif unit == 'minutes':
            if isinstance(delta, (int, float)):
                new_time = self.base_time - datetime.timedelta(minutes=delta)
                return new_time
            else:
                raise TypeError("Delta for minutes must be a number.")
        elif unit == 'hours':
            if isinstance(delta, (int, float)):
                new_time = self.base_time - datetime.timedelta(hours=delta)
                return new_time
            else:
                raise TypeError("Delta for hours must be a number.")
        else:
            raise ValueError("Unsupported time unit. Use 'seconds', 'minutes', or 'hours'.")
if __name__ == '__main__':
    print("--- Time Calculation Module Test ---")
    start_time = datetime.datetime(2023, 10, 27, 10, 30, 0)
    print(f"Base Time: {start_time}")
    calculator = TimeCalculator(base_time=start_time)
    delta_seconds = 3600          
    try:
        time_after_seconds = calculator.add_time(delta_seconds, unit='seconds')
        print(f"Adding {delta_seconds} seconds: {time_after_seconds}")
    except (TypeError, ValueError) as e:
        print(f"Error adding seconds: {e}")
    delta_minutes = 90
    try:
        time_after_minutes = calculator.add_time(delta_minutes, unit='minutes')
        print(f"Adding {delta_minutes} minutes: {time_after_minutes}")
    except (TypeError, ValueError) as e:
        print(f"Error adding minutes: {e}")
    delta_hours = 2
    try:
        time_before_hours = calculator.subtract_time(delta_hours, unit='hours')
        print(f"Subtracting {delta_hours} hours: {time_before_hours}")
    except (TypeError, ValueError) as e:
        print(f"Error subtracting hours: {e}")
    try:
        calculator.add_time(10, unit='days')
    except ValueError as e:
        print(f"Caught expected error for invalid unit: {e}")
    try:
        calculator.add_time("invalid", unit='seconds')
    except TypeError as e:
        print(f"Caught expected error for invalid delta type: {e}")

import datetime
class TimeCalculator:
    def __init__(self, base_time=None):
        self.base_time = base_time
    def add_time(self, delta, unit='seconds'):
        if self.base_time is None:
            raise ValueError("Base time must be set before performing calculations.")
        if unit == 'seconds':
            result = self.base_time + datetime.timedelta(seconds=delta)
        elif unit == 'minutes':
            result = self.base_time + datetime.timedelta(minutes=delta)
        elif unit == 'hours':
            result = self.base_time + datetime.timedelta(hours=delta)
        else:
            raise ValueError("Unsupported time unit. Use 'seconds', 'minutes', or 'hours'.")
        return result
    def subtract_time(self, delta, unit='seconds'):
        if self.base_time is None:
            raise ValueError("Base time must be set before performing calculations.")
        if unit == 'seconds':
            result = self.base_time - datetime.timedelta(seconds=delta)
        elif unit == 'minutes':
            result = self.base_time - datetime.timedelta(minutes=delta)
        elif unit == 'hours':
            result = self.base_time - datetime.timedelta(hours=delta)
        else:
            raise ValueError("Unsupported time unit. Use 'seconds', 'minutes', or 'hours'.")
        return result
    def get_time_difference(self, end_time, start_time):
        if not isinstance(start_time, datetime.datetime) or not isinstance(end_time, datetime.datetime):
            raise TypeError("Both start_time and end_time must be datetime objects.")
        if start_time > end_time:
            return -1                                                                      
        difference = end_time - start_time
        return difference
if __name__ == '__main__':
    start = datetime.datetime(2023, 10, 26, 10, 0, 0)
    calculator = TimeCalculator(base_time=start)
    print(f"Base Time: {start}")
    try:
        time_plus_minutes = calculator.add_time(30, unit='minutes')
        print(f"Time + 30 minutes: {time_plus_minutes}")
        time_plus_hours = calculator.add_time(2, unit='hours')
        print(f"Time + 2 hours: {time_plus_hours}")
        time_minus_seconds = calculator.subtract_time(60, unit='seconds')
        print(f"Time - 60 seconds: {time_minus_seconds}")
        end = datetime.datetime(2023, 10, 26, 11, 30, 0)
        diff = calculator.get_time_difference(end, start)
        print(f"Difference between start and end: {diff}")
        try:
            calculator.add_time(10, unit='days')
        except ValueError as e:
            print(f"Caught expected error: {e}")
        try:
            calculator.add_time(10, unit='weeks')
        except ValueError as e:
            print(f"Caught expected error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

import datetime
class TimeCalculator:
    def __init__(self, base_format="%Y-%m-%d %H:%M:%S"):
        self.base_format = base_format
    def parse_time(self, time_str):
        try:
            dt = datetime.datetime.strptime(time_str, self.base_format)
            return dt
        except ValueError as e:
            raise ValueError(f"Invalid date format. Expected '{self.base_format}': {e}")
    def add_duration(self, dt, duration_str):
        try:
            duration = datetime.timedelta(seconds=int(duration_str))
            new_dt = dt + duration
            return new_dt
        except ValueError:
            raise ValueError("Invalid duration format. Must be an integer number of seconds.")
    def format_time(self, dt, output_format="%Y-%m-%d %H:%M:%S"):
        try:
            return dt.strftime(output_format)
        except Exception as e:
            raise RuntimeError(f"Error formatting time: {e}")
if __name__ == '__main__':
    calculator = TimeCalculator()
    sample_date_str = "2023-10-27 10:00:00"
    sample_duration_str = "3600"
    try:
        start_time = calculator.parse_time(sample_date_str)
        print(f"Start Time: {calculator.format_time(start_time)}")
        end_time = calculator.add_duration(start_time, sample_duration_str)
        print(f"End Time (after adding {sample_duration_str} seconds): {calculator.format_time(end_time)}")
        another_time_str = "2024-01-01 00:00:00"
        another_duration_str = "86400"
        start_time_2 = calculator.parse_time(another_time_str)
        end_time_2 = calculator.add_duration(start_time_2, another_duration_str)
        print(f"Second Test: Start Time: {calculator.format_time(start_time_2)}, End Time: {calculator.format_time(end_time_2)}")
        try:
            calculator.parse_time("27/10/2023 10:00")
        except ValueError as e:
            print(f"Error Handling Test Passed: {e}")
    except ValueError as e:
        print(f"A critical error occurred during time calculation: {e}")
    except RuntimeError as e:
        print(f"A formatting error occurred: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

import datetime
class TimeCalculator:
    def __init__(self, base_time=None):
        self.base_time = base_time if base_time is not None else datetime.datetime.now()
    def add_time(self, delta, unit='seconds'):
        if unit == 'seconds':
            if isinstance(delta, (int, float)):
                new_time = self.base_time + datetime.timedelta(seconds=delta)
                return new_time
            else:
                raise TypeError("Delta for seconds must be a number.")
        elif unit == 'minutes':
            if isinstance(delta, (int, float)):
                new_time = self.base_time + datetime.timedelta(minutes=delta)
                return new_time
            else:
                raise TypeError("Delta for minutes must be a number.")
        elif unit == 'hours':
            if isinstance(delta, (int, float)):
                new_time = self.base_time + datetime.timedelta(hours=delta)
                return new_time
            else:
                raise TypeError("Delta for hours must be a number.")
        else:
            raise ValueError("Unsupported time unit. Use 'seconds', 'minutes', or 'hours'.")
    def subtract_time(self, delta, unit='seconds'):
        if unit == 'seconds':
            if isinstance(delta, (int, float)):
                new_time = self.base_time - datetime.timedelta(seconds=delta)
                return new_time
            else:
                raise TypeError("Delta for seconds must be a number.")
        elif unit == 'minutes':
            if isinstance(delta, (int, float)):
                new_time = self.base_time - datetime.timedelta(minutes=delta)
                return new_time
            else:
                raise TypeError("Delta for minutes must be a number.")
        elif unit == 'hours':
            if isinstance(delta, (int, float)):
                new_time = self.base_time - datetime.timedelta(hours=delta)
                return new_time
            else:
                raise TypeError("Delta for hours must be a number.")
        else:
            raise ValueError("Unsupported time unit. Use 'seconds', 'minutes', or 'hours'.")
    def get_time_difference(self, end_time, unit='seconds'):
        if not isinstance(end_time, datetime.datetime):
            raise TypeError("end_time must be a datetime object.")
        difference = end_time - self.base_time
        if unit == 'seconds':
            return difference.total_seconds()
        elif unit == 'minutes':
            return difference.total_seconds() / 60
        elif unit == 'hours':
            return difference.total_seconds() / 3600
        else:
            raise ValueError("Unsupported difference unit. Use 'seconds', 'minutes', or 'hours'.")
if __name__ == '__main__':
    start_time = datetime.datetime(2023, 10, 27, 10, 0, 0)
    calculator = TimeCalculator(base_time=start_time)
