    try:
        start_date = datetime.datetime.strptime(start_date_str, "%Y-%m-%d").date()
        days_to_add = int(days_to_add_str)
        if days_to_add < 0:
            return "Error: Number of days cannot be negative."
        future_date = start_date + datetime.timedelta(days=days_to_add)
