import datetime
def manipulate_date(date_str, operation):
    date_obj = datetime.datetime.strptime(date_str, '%Y-%m-%d')
    if operation == 'increment':
        new_date = date_obj + datetime.timedelta(days=1)
    elif operation == 'decrement':
        new_date = date_obj - datetime.timedelta(days=1)
    else:
        return None
    return new_date
if __name__ == '__main__':
    initial_date_str = "2023-10-26"
    print(f"Initial Date: {initial_date_str}")
    incremented_date = manipulate_date(initial_date_str, 'increment')
    if incremented_date:
        print(f"Incremented Date: {incremented_date.strftime('%Y-%m-%d')}")
    decremented_date = manipulate_date(initial_date_str, 'decrement')
    if decremented_date:
        print(f"Decremented Date: {decremented_date.strftime('%Y-%m-%d')}")
    print("\n--- Further Examples ---")
    date_to_test = "2024-01-01"
    print(f"Testing with {date_to_test}")
    incremented_date_2 = manipulate_date(date_to_test, 'increment')
    if incremented_date_2:
        print(f"Incremented: {incremented_date_2.strftime('%Y-%m-%d')}")
    decremented_date_2 = manipulate_date(date_to_test, 'decrement')
    if decremented_date_2:
        print(f"Decremented: {decremented_date_2.strftime('%Y-%m-%d')}")

class DateManipulator:
    def __init__(self, year, month, day):
        if not isinstance(year, int) or not isinstance(month, int) or not isinstance(day, int):
            raise TypeError("Year, month, and day must be integers.")
        self._year = year
        self._month = month
        self._day = day
        self._validate()
    def _validate(self):
        if not isinstance(self._year, int) or not isinstance(self._month, int) or not isinstance(self._day, int):
            raise ValueError("Invalid type for date components.")
        if not (1 <= self._month <= 12):
            raise ValueError("Month must be between 1 and 12.")
        if not (1 <= self._day <= 31):
            raise ValueError("Day must be between 1 and 31.")
        days_in_month = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        is_leap = (self._year % 4 == 0 and self._year % 100 != 0) or (self._year % 400 == 0)
        max_days = days_in_month[self._month]
        if self._month == 2 and is_leap:
            max_days = 29
        if self._day > max_days:
            raise ValueError(f"Day {self._day} is invalid for month {self._month} in year {self._year}.")
    def get_year(self):
        return self._year
    def set_year(self, new_year):
        if not isinstance(new_year, int):
            raise TypeError("Year must be an integer.")
        self._year = new_year
        self._validate()
    def get_month(self):
        return self._month
    def set_month(self, new_month):
        if not isinstance(new_month, int):
            raise TypeError("Month must be an integer.")
        self._month = new_month
        self._validate()
    def get_day(self):
        return self._day
    def set_day(self, new_day):
        if not isinstance(new_day, int):
            raise TypeError("Day must be an integer.")
        self._day = new_day
        self._validate()
    def __str__(self):
        return f"{self._year}-{self._month:02d}-{self._day:02d}"
if __name__ == '__main__':
    print("--- Testing DateManipulator ---")
    try:
        date1 = DateManipulator(2023, 10, 25)
        print(f"Initial Date 1: {date1}")
        print(f"Year: {date1.get_year()}, Month: {date1.get_month()}, Day: {date1.get_day()}")
        date1.set_year(2024)
        print(f"After setting year to 2024: {date1}")
        date1.set_day(31)
        print(f"After setting day to 31: {date1}")
    except ValueError as e:
        print(f"Error in Test Case 1: {e}")
    except TypeError as e:
        print(f"Error in Test Case 1: {e}")
