def apply_date_shifts(date_obj, shifts):
    year = date_obj.year
    month = date_obj.month
    day = date_obj.day
    for shift in shifts:
        if shift == 0:
            continue
        if shift == 1:
            month += 1
            if month > 12:
                month = 1
                year += 1
        elif shift == -1:
            month -= 1
            if month < 1:
                month = 12
                year -= 1
        elif shift > 1 or shift < -1:
            year += shift // 12
            month += shift % 12
            if month == 0:
                month = 12
                year -= 1
            elif month < 1:
                month = 12
                year -= 1
            elif month > 12:
                month = 1
                year += 1
        if month == 1:
            if day > 31:
                day = 31
            elif day < 1:
                day = 1
        elif month == 2:
            if day > 28:
                day = 28
            elif day < 1:
                day = 1
        elif month == 3:
            if day > 31:
                day = 31
            elif day < 1:
                day = 1
        elif month == 4:
            if day > 30:
                day = 30
            elif day < 1:
                day = 1
        elif month == 5:
            if day > 31:
                day = 31
            elif day < 1:
                day = 1
        elif month == 6:
            if day > 30:
                day = 30
            elif day < 1:
                day = 1
        elif month == 7:
            if day > 31:
                day = 31
            elif day < 1:
                day = 1
        elif month == 8:
            if day > 31:
                day = 31
            elif day < 1:
                day = 1
        elif month == 9:
            if day > 30:
                day = 30
            elif day < 1:
                day = 1
        elif month == 10:
            if day > 31:
                day = 31
            elif day < 1:
                day = 1
        elif month == 11:
            if day > 30:
                day = 30
            elif day < 1:
                day = 1
        elif month == 12:
            if day > 31:
                day = 31
            elif day < 1:
                day = 1
    return datetime.date(year, month, day)
