def multiply_by_constant(factor):
    def decorator(func):
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs) * factor
        return wrapper
    return decorator
@multiply_by_constant(5)
def double(x):
    return x * 2
@multiply_by_constant(10)
def triple(x):
    return x * 3
if __name__ == '__main__':
    result_double = double(4)
    result_triple = triple(5)
    print(f"double(4): {result_double}")
    print(f"triple(5): {result_triple}")

def multiply_by_constant(factor):
    def decorator(func):
        def wrapper(*args, **kwargs):
            result = func(*args, **kwargs)
            return result * factor
        return wrapper
    return decorator
@multiply_by_constant(5)
def double(x):
    return x * 2
@multiply_by_constant(10)
def add_ten(x):
    return x + 10
if __name__ == '__main__':
    print(double(3))
    print(add_ten(5))

import unittest
def multiply(a, b):
    return a * b
class TestMultiply(unittest.TestCase):
    def test_positive_numbers(self):
        self.assertEqual(multiply(2, 3), 6)
        self.assertEqual(multiply(5, 4), 20)
    def test_negative_numbers(self):
        self.assertEqual(multiply(-2, 3), -6)
        self.assertEqual(multiply(4, -5), -20)
        self.assertEqual(multiply(-4, -5), 20)
    def test_zero(self):
        self.assertEqual(multiply(0, 5), 0)
        self.assertEqual(multiply(10, 0), 0)
        self.assertEqual(multiply(0, 0), 0)
    def test_large_numbers(self):
        self.assertEqual(multiply(100, 200), 20000)
        self.assertEqual(multiply(-10, 50), -500)
if __name__ == '__main__':
    unittest.main(argv=['first-arg-is-ignored'], exit=False)

