    list_b = [5, 15, 25]
    result1 = compare_quantities(list_a, list_b)
    print(result1)
    list_c = [1, 2, 3]
    list_d = [100, 200]
    result2 = compare_quantities(list_c, list_d)
    print(result2)
    list_e = [50, 50]
    list_f = [50, 50]
    result3 = compare_quantities(list_e, list_f)
    print(result3)

