class QuantityComparator:
    def compare_quantities(self, quantity1, quantity2):
        size1 = len(quantity1)
        size2 = len(quantity2)
        if size1 > size2:
            return f"Quantity 1 (size {size1}) is larger than Quantity 2 (size {size2})"
        elif size2 > size1:
            return f"Quantity 2 (size {size2}) is larger than Quantity 1 (size {size1})"
        else:
            return f"Quantity 1 and Quantity 2 have the same size ({size1})"
if __name__ == '__main__':
    comparator = QuantityComparator()
    q1 = [1, 2, 3, 4]
    q2 = [5, 6]
    q3 = [10, 20, 30, 40]
    q4 = [5, 5]
    print(comparator.compare_quantities(q1, q2))
    print(comparator.compare_quantities(q2, q1))
    print(comparator.compare_quantities(q3, q4))
    print(comparator.compare_quantities(q4, q4))

class QuantityComparator:
    def compare_quantities(self, quantity1, quantity2):
        if len(quantity1) != len(quantity2):
            return "Quantities have different numbers of elements."
        if not quantity1:
            return "Both quantities are empty."
        sum1 = sum(quantity1)
        sum2 = sum(quantity2)
        if sum1 > sum2:
            return "Quantity 1 is larger."
        elif sum1 < sum2:
            return "Quantity 2 is larger."
        else:
            return "The quantities are equal in total size."
if __name__ == '__main__':
    comparator = QuantityComparator()
    q1 = [10, 20, 30]
    q2 = [5, 15, 25]
    q3 = [1, 2, 3]
    q4 = [10, 10, 10]
    q5 = [5, 5]
    print(f"Comparing {q1} and {q2}: {comparator.compare_quantities(q1, q2)}")
    print(f"Comparing {q3} and {q4}: {comparator.compare_quantities(q3, q4)}")
    print(f"Comparing {q1} and {q1}: {comparator.compare_quantities(q1, q1)}")
    print(f"Comparing {q5} and {q2}: {comparator.compare_quantities(q5, q2)}")
    print(f"Comparing {q1} and [10, 20, 30, 40]: {comparator.compare_quantities(q1, [10, 20, 30, 40])}")

def compare_lengths(str1, str2):
