            try:
                nums = [int(x) for x in expr.split('+')]
                if len(nums) >= 2:
                    current_result = nums[0]
                    for i in range(1, len(nums)):
                        current_result += nums[i]
                    results.append(current_result)
            except ValueError:
                pass
        elif '-' in expr:
            try:
                parts = expr.split('-')
                if len(parts) == 2:
                    a = int(parts[0])
                    b = int(parts[1])
                    results.append(a - b)
                elif len(parts) > 2:
                    nums = [int(x) for x in parts]
                    current_result = nums[0]
                    for i in range(1, len(nums)):
                        current_result -= nums[i]
                    results.append(current_result)
            except ValueError:
                pass
    return results
