def analyze_numbers(numbers):
    odd_count = 0
    for num in numbers:
        if num % 2 != 0:
            odd_count += 1
    if odd_count % 2 == 0:
        print("The number of odd numbers is even.")
    else:
        print("The number of odd numbers is odd.")
