def resolve_decision_tree(node, value):
    if node == "A":
        if value > 10:
            return value * 2
        else:
            return value + 5
    elif node == "B":
        if value % 2 == 0:
            return value // 2
        else:
            return value + 1
    elif node == "C":
        if value < 5:
            return value - 1
        else:
            return value * 3
    else:
        return value
