    test_cases = [
        (("A", 15), 0),
        (("A", 5), 0),
        (("B", 10), 0),
        (("B", 7), 0),
        (("C", 3), 0),
        (("C", 8), 0),
        (("D", 100), 0)
    ]
    for (node, value), expected in test_cases:
        result = resolve_decision_tree(node, value)
        print(f"Node: {node}, Value: {value}, Result: {result}, Expected: {expected}, Match: {result == expected}")

