class RuleBasedMapper:
    def __init__(self):
        self.rules = []
    def add_rule(self, conditions, output):
        self.rules.append((conditions, output))
    def map(self, input_conditions):
        for conditions, output in self.rules:
            if conditions == input_conditions:
                return output
        return None
