def are_mutually_exclusive(constraints):
    if not constraints:
        return True
    all_constraints = set()
    for constraint_set in constraints:
        all_constraints.update(constraint_set)
    if len(all_constraints) == 0:
        return True
    for constraint_set in constraints:
        if not constraint_set.issubset(all_constraints):
            return False
    return True
