import itertools
def check_mutual_exclusivity(states):
    exclusive_pairs = []
    for state1, state2 in itertools.combinations(states, 2):
        if state1 == state2:
            continue
        if state1 in state2 or state2 in state1:
            exclusive_pairs.append((state1, state2))
    return exclusive_pairs
if __name__ == '__main__':
    state_definitions = [
        "A",
        "B",
        "C",
        "D",
        "E"
    ]
    results = check_mutual_exclusivity(state_definitions)
    print("Mutual Exclusivity Report:")
    if results:
        for s1, s2 in results:
            print(f"States {s1} and {s2} are mutually exclusive.")
    else:
        print("No mutually exclusive pairs found.")

import itertools
def check_mutual_exclusivity(states):
    mutually_exclusive_pairs = []
    state_list = list(states)
    for state1, state2 in itertools.combinations(state_list, 2):
        if state1 == state2:
            continue
        if state1 in state2 or state2 in state1:
            mutually_exclusive_pairs.append((state1, state2))
    return mutually_exclusive_pairs
if __name__ == '__main__':
    defined_states = [
        "A",
        "B",
        "C",
        "D",
        "E"
    ]
    results = check_mutual_exclusivity(defined_states)
    print("Mutual Exclusivity Report:")
    if results:
        for pair in results:
            print(f"States {pair[0]} and {pair[1]} are mutually exclusive.")
    else:
        print("No mutually exclusive pairs found.")

class ConstraintManager:
    def __init__(self):
        self.constraints = set()
    def add_constraint(self, constraint):
        self.constraints.add(constraint)
    def is_mutually_exclusive(self, new_constraint):
        for existing_constraint in self.constraints:
            if existing_constraint == new_constraint:
                return True
        return False
if __name__ == '__main__':
    manager = ConstraintManager()
    constraint1 = "A"
    constraint2 = "B"
    constraint3 = "A"
    manager.add_constraint(constraint1)
    manager.add_constraint(constraint2)
    print(f"Is '{constraint1}' mutually exclusive with existing constraints? {manager.is_mutually_exclusive(constraint1)}")
    print(f"Is '{constraint2}' mutually exclusive with existing constraints? {manager.is_mutually_exclusive(constraint2)}")
    print(f"Is '{constraint3}' mutually exclusive with existing constraints? {manager.is_mutually_exclusive(constraint3)}")
    manager.add_constraint("C")
    print(f"Is 'C' mutually exclusive with existing constraints? {manager.is_mutually_exclusive('C')}")

