def are_contradictory(cond1, cond2):
    if not cond1 or not cond2:
        return False
    set1 = set(cond1)
    set2 = set(cond2)
    intersection = set1.intersection(set2)
    for item in intersection:
        if len(item) == 2:
            attr1, val1 = item
            attr2, val2 = item
            if attr1 == attr2:
                if val1 != val2:
                    return True
    return False
