import itertools
def check_mutual_exclusivity(properties):
    n = len(properties)
    is_exclusive = [False] * n
    for i in range(n):
        for j in range(i + 1, n):
            if properties[i] == properties[j]:
                is_exclusive[i] = True
                is_exclusive[j] = True
    return is_exclusive
