            if not evaluate_expression(part, context):
                result = False
                break
        return result
    if 'or' in expression:
        parts = [p.strip() for p in expression.split('or')]
        result = False
        for part in parts:
            if evaluate_expression(part, context):
                result = True
                break
        return result
    if 'not' in expression:
        parts = [p.strip() for p in expression.split('not')]
        if len(parts) == 2:
