class LogicalOperations:
    def apply_operators(self, expressions):
        results = []
        for expr in expressions:
            if isinstance(expr, list):
                result = expr[0]
                for i in range(1, len(expr)):
                    result = result and expr[i]
                results.append(result)
            else:
                results.append(expr)
        return results
