import sympy
def simplify_expression(expression_str):
    try:
        expr = sympy.sympify(expression_str)
        return expr.simplify()
    except sympy.SympifyError:
        return None
def evaluate_and_compare(expr1_str, expr2_str, variables):
    try:
        expr1 = sympy.sympify(expr1_str)
        expr2 = sympy.sympify(expr2_str)
        expr1_sub = expr1.subs(variables, {v: 1 for v in variables})
        expr2_sub = expr2.subs(variables, {v: 1 for v in variables})
        return expr1.equals(expr2)
    except Exception:
        return False
def check_equivalence(expr1_str, expr2_str, variables):
    if expr1_str == expr2_str:
        return True
    try:
        expr1 = sympy.sympify(expr1_str)
        expr2 = sympy.sympify(expr2_str)
        all_vars = set()
        for s in [expr1_str, expr2_str]:
            for char in s:
                if 'a' <= char <= 'z':
                    all_vars.add(char)
        if not all_vars:
            return sympy.simplify(expr1) == sympy.simplify(expr2)
        var_list = sorted(list(all_vars))
        n = len(var_list)
        for i in range(2**n):
            assignment = {}
            temp_i = i
            for j in range(n):
                assignment[var_list[j]] = bool(temp_i & 1)
                temp_i >>= 1
            try:
                val1 = expr1.subs(assignment, {v: 1 if v in ('True', 'True') else 0 for v in var_list})
                val2 = expr2.subs(assignment, {v: 1 if v in ('True', 'True') else 0 for v in var_list})
                if val1 != val2:
                    return False
            except Exception:
                continue
        return True
    except Exception:
        return False
if __name__ == '__main__':
    expr1 = "a AND (b OR c)"
    expr2 = "(a AND b) OR c"
    variables = ['a', 'b', 'c']
    result = check_equivalence(expr1, expr2, variables)
    print(f"Expression 1: {expr1}")
    print(f"Expression 2: {expr2}")
    print(f"Variables: {variables}")
    print(f"Logical Equivalence: {result}")
    print("-" * 20)
    expr3 = "a OR (b AND c)"
    expr4 = "(a OR b) AND (a OR c)"
    result2 = check_equivalence(expr3, expr4, variables)
    print(f"Expression 3: {expr3}")
    print(f"Expression 4: {expr4}")
    print(f"Variables: {variables}")
    print(f"Logical Equivalence: {result2}")

import sympy
def simplify_expression(expression_str):
    try:
        expr = sympy.sympify(expression_str)
        return expr.simplify()
    except sympy.SympifyError:
        return None
def check_equivalence(expr1_str, expr2_str, variables):
    try:
        expr1 = sympy.sympify(expr1_str)
        expr2 = sympy.sympify(expr2_str)
        subs1 = {var: sympy.Symbol(var) for var in variables}
        expr1_subs = expr1.subs(subs1)
        expr2_subs = expr2.subs(subs1)
        return expr1_subs == expr2_subs
    except Exception:
        return False
if __name__ == '__main__':
    expr1_str = "(A AND B) OR (NOT A AND C)"
    expr2_str = "(A OR B) AND (A OR C)"
    variables = ['A', 'B', 'C']
    result = check_equivalence(expr1_str, expr2_str, variables)
    print(f"Expression 1: {expr1_str}")
    print(f"Expression 2: {expr2_str}")
    print(f"Variables: {variables}")
    print(f"Logical Equivalence: {result}")

import sympy
def simplify_expression(expression_str):
    try:
        expr = sympy.sympify(expression_str)
        return sympy.simplify(expr)
    except sympy.SympifyError:
        return None
def evaluate_and_compare(expr1_str, expr2_str, variables):
    try:
        expr1 = sympy.sympify(expr1_str)
        expr2 = sympy.sympify(expr2_str)
        expr1_sub = expr1.subs(variables, {var: 1 for var in variables})
        expr2_sub = expr2.subs(variables, {var: 1 for var in variables})
        return sympy.simplify(expr1_sub) == sympy.simplify(expr2_sub)
    except Exception:
        return False
def check_equivalence(expr1_str, expr2_str, variables):
    if not variables:
        return False
    context = {var: True for var in variables}
    try:
        expr1 = sympy.sympify(expr1_str)
        expr2 = sympy.sympify(expr2_str)
        expr1_eval = expr1.subs(variables, context)
        expr2_eval = expr2.subs(variables, context)
        return sympy.simplify(expr1_eval) == sympy.simplify(expr2_eval)
    except Exception:
        return False
if __name__ == '__main__':
    expr_a = "(p AND q) OR (NOT p)"
    expr_b = "q OR (NOT p)"
    vars_1 = ['p', 'q']
    expr_c = "p OR q"
    expr_d = "(p OR q)"
    vars_2 = ['p', 'q']
    expr_e = "p AND (q OR r)"
    expr_f = "(p AND q) OR r"
    vars_3 = ['p', 'q', 'r']
    print(f"Expression A: {expr_a}")
    print(f"Expression B: {expr_b}")
    result_1 = check_equivalence(expr_a, expr_b, vars_1)
    print(f"Equivalence (A vs B): {result_1}\n")
    print(f"Expression C: {expr_c}")
    print(f"Expression D: {expr_d}")
    result_2 = check_equivalence(expr_c, expr_d, vars_2)
    print(f"Equivalence (C vs D): {result_2}\n")
    print(f"Expression E: {expr_e}")
    print(f"Expression F: {expr_f}")
    result_3 = check_equivalence(expr_e, expr_f, vars_3)
    print(f"Equivalence (E vs F): {result_3}\n")

import sympy
def simplify_expression(expression_str):
    try:
        expr = sympy.sympify(expression_str)
        return sympy.simplify(expr)
    except sympy.SympifyError:
        return None
def evaluate_and_compare(expr1_str, expr2_str, variables):
    try:
        expr1 = sympy.sympify(expr1_str)
        expr2 = sympy.sympify(expr2_str)
        subs1 = {var: float(val) for var, val in variables.items()}
        subs2 = {var: float(val) for var, val in variables.items()}
        val1 = expr1.subs(subs1).evalf()
        val2 = expr2.subs(subs2).evalf()
        return abs(val1 - val2) < 1e-9
    except Exception:
        return False
def find_variables(expression_str):
    import re
    variables = set()
    for match in re.findall(r'[a-zA-Z_][a-zA-Z0-9_]*', expression_str):
        variables.add(match)
    return sorted(list(variables))
if __name__ == '__main__':
    expression1 = "A + B"
    expression2 = "(A + B)"
    variables = {'A': 2, 'B': 3}
    print(f"Expression 1: {expression1}")
    print(f"Expression 2: {expression2}")
    print(f"Variables: {variables}")
    is_equivalent = evaluate_and_compare(expression1, expression2, variables)
    print(f"Are the expressions logically equivalent for these values? {is_equivalent}")
    expression3 = "A * (B + C)"
    expression4 = "(A * B) + (A * C)"
    variables_3 = {'A': 1, 'B': 2, 'C': 4}
    print(f"\nExpression 3: {expression3}")
    print(f"Expression 4: {expression4}")
    print(f"Variables: {variables_3}")
    is_equivalent_2 = evaluate_and_compare(expression3, expression4, variables_3)
    print(f"Are the expressions logically equivalent for these values? {is_equivalent_2}")

import sympy
def simplify_expression(expression_str):
    try:
        expr = sympy.sympify(expression_str)
        return sympy.simplify(expr)
    except sympy.SympifyError:
        return None
def evaluate_and_compare(expr1_str, expr2_str, variables):
    try:
        expr1 = sympy.sympify(expr1_str)
        expr2 = sympy.sympify(expr2_str)
        expr1_subs = expr1.subs(variables)
        expr2_subs = expr2.subs(variables)
        simplified_expr1 = sympy.simplify(expr1_subs)
        simplified_expr2 = sympy.simplify(expr2_subs)
        return simplified_expr1 == simplified_expr2
    except Exception:
        return False
if __name__ == '__main__':
    expression1 = "A & ~B"
    expression2 = "~A | B"
    variables = {'A': sympy.Symbol('A'), 'B': sympy.Symbol('B')}
    result = evaluate_and_compare(expression1, expression2, variables)
    print(f"Expression 1: {expression1}")
    print(f"Expression 2: {expression2}")
    print(f"Logical Equivalence: {result}")
    expression3 = "(A | B) & C"
    expression4 = "A & (B | C)"
    variables = {'A': sympy.Symbol('A'), 'B': sympy.Symbol('B'), 'C': sympy.Symbol('C')}
    result2 = evaluate_and_compare(expression3, expression4, variables)
    print(f"\nExpression 3: {expression3}")
    print(f"Expression 4: {expression4}")
    print(f"Logical Equivalence: {result2}")

import sympy
def simplify_expression(expression_str):
    try:
        expr = sympy.sympify(expression_str)
        return expr.simplify()
    except sympy.SympifyError:
        return None
def check_equivalence(expr1_str, expr2_str, variables):
    try:
        expr1 = sympy.sympify(expr1_str)
        expr2 = sympy.sympify(expr2_str)
        expr1_subs = expr1.subs(variables, {v: sympy.Symbol(v) for v in variables})
        expr2_subs = expr2.subs(variables, {v: sympy.Symbol(v) for v in variables})
        return expr1_subs == expr2_subs
    except Exception:
        return False
if __name__ == '__main__':
    expr1_str = "(A OR B) AND (NOT A OR C)"
    expr2_str = "(A OR C) AND (NOT A OR B)"
    variables = ['A', 'B', 'C']
    result = check_equivalence(expr1_str, expr2_str, variables)
    print(f"Expression 1: {expr1_str}")
    print(f"Expression 2: {expr2_str}")
    print(f"Logical Equivalence: {result}")

