def generate_or_truth_table(bool_list):
    n = len(bool_list)
    rows = 2**n
    truth_table = []
    for i in range(rows):
        row = []
        for j in range(n):
            if (i >> j) & 1:
                row.append(bool_list[j])
            else:
                row.append(not bool_list[j])
        truth_table.append(row)
    return truth_table
if __name__ == '__main__':
    sample_inputs = [False, True]
    truth_table_result = generate_or_truth_table(sample_inputs)
    for row in truth_table_result:
        print(row)

class BooleanLogic:
    def calculate_table(self):
        P_values = [0, 1]
        Q_values = [0, 1]
        results = []
        for p in P_values:
            for q in Q_values:
                p_and_q = p & q
                results.append((p, q, p_and_q))
        print("P | Q | P AND Q")
        print("---|---|---------")
        for p, q, result in results:
            print(f"{p} | {q} | {result}")
if __name__ == '__main__':
    logic = BooleanLogic()
    logic.calculate_table()

class BooleanLogic:
    def calculate_table(self):
        P_values = [0, 1]
        Q_values = [0, 1]
        results = []
        operation = lambda p, q: p and q
        for p in P_values:
            for q in Q_values:
                result = operation(p, q)
                results.append((p, q, result))
        return results
if __name__ == '__main__':
    bl = BooleanLogic()
    table = bl.calculate_table()
    print("P | Q | P AND Q")
    for p, q, result in table:
        print(f"{p} | {q} | {result}")

