    result_or = evaluate_gate(A_val, B_val, 'OR')
    print(f"A={A_val}, B={B_val}, OR: {result_or}")
    result_not = evaluate_gate(A_val, B_val, 'NOT')
    print(f"A={A_val}, B={B_val}, NOT: {result_not}")

def evaluate_gate(A, B, gate_type):
    if gate_type == 'AND':
        return A and B
    elif gate_type == 'OR':
        return A or B
    elif gate_type == 'NOT':
        return not A
    else:
        raise ValueError("Invalid gate type")
if __name__ == '__main__':
    print(f"AND(True, True): {evaluate_gate(True, True, 'AND')}")
    print(f"AND(True, False): {evaluate_gate(True, False, 'AND')}")
    print(f"OR(True, False): {evaluate_gate(True, False, 'OR')}")
