    print(final_result)

def evaluate_nested_conditions(conditions):
    result = None
    for condition_set in conditions:
        if result is None:
            result = True
            for sub_condition, sub_result in condition_set:
                if not sub_result:
                    result = False
                    break
        else:
            for sub_condition, sub_result in condition_set:
                if not sub_result:
                    result = False
                    break
        if not result:
            break
    return result
