        sample_conditions = [
            ("a", True),
            ("b", False)
        ]
        assert check_all_conditions(sample_conditions) is False
    def test_analyze_and_verify_mixed(self):
        sample_conditions = [
            ("A", True),
            ("B", False),
            ("C", True)
        ]
        expected = {
            "A": True,
            "B": False,
            "C": True,
            "all_true": False
        }
        actual = analyze_and_verify(sample_conditions)
        assert actual == expected
