def evaluate_condition(condition, truth_values):
    if not condition:
        return True
    parts = condition.split(' and ')
    for part in parts:
        if not part:
            continue
        if '=' in part:
            var, val_str = part.split('=', 1)
            var = var.strip()
            val = eval(val_str.strip())
            if var not in truth_values:
                return False
            if truth_values[var] != val:
                return False
        else:
            return False 
    return True
