import itertools
def generate_truth_table(inputs):
    num_inputs = len(inputs)
    num_rows = 2**num_inputs
    truth_table = []
    for i in range(num_rows):
        input_values = []
        temp = i
        for _ in range(num_inputs):
            input_values.append(temp % 2)
            temp //= 2
        input_values.reverse()
        output = []
        for input_tuple in itertools.product([0, 1], repeat=num_inputs):
            output_tuple = []
            for input_val in input_tuple:
                result = 0
                for input_val_idx in range(num_inputs):
                    if input_val_idx == len(input_tuple) - 1 - input_val_idx:
                        result = input_val
                    else:
                        result = input_val or (input_val_idx == 0 and input_val == 1)
                output_tuple.append(result)
            truth_table.append(output_tuple)
    return truth_table
