def evaluate_boolean_expression(P, Q, expression):
    if expression == "P and Q":
        return P and Q
    elif expression == "P or Q":
        return P or Q
    elif expression == "not P":
        return not P
    elif expression == "not Q":
        return not Q
    elif expression == "P and not Q":
        return P and (not Q)
    elif expression == "P or not Q":
        return P or (not Q)
    elif expression == "P and Q or Q":
        return (P and Q) or Q
    elif expression == "P or Q and P":
        return (P or Q) and P
    elif expression == "P and Q and not P":
        return False
    elif expression == "P or Q and not P":
        return True
    elif expression == "not P and Q":
        return (not P) and Q
    elif expression == "not P and not Q":
        return (not P) and (not Q)
    elif expression == "not (P and Q)":
        return not (P and Q)
    elif expression == "P xor Q":
