def generate_truth_table(expression, var1_name, var2_name, num_rows):
    truth_table = []
    for i in range(2**num_rows):
        row = []
        for j in range(num_rows):
            var1_val = (i >> j) & 1
            var2_val = (i >> (j + 1)) & 1
            if var1_name == "A":
                val1 = bool(var1_val)
            elif var2_name == "B":
                val2 = bool(var2_val)
            else:
                val1 = var1_val
                val2 = var2_val
            row.append(val1)
        A = (i >> 0) & 1
        B = (i >> 1) & 1
        result = False
        if "A" in expression:
            A_val = A
        else:
            A_val = False
        if "B" in expression:
            B_val = B
        else:
            B_val = False
        if "AND" in expression:
            result = A_val and B_val
        elif "OR" in expression:
            result = A_val or B_val
        elif "NOT" in expression:
            if "A" in expression:
                result = not A_val
            elif "B" in expression:
                result = not B_val
        else:
            result = A_val                                
        row.append(result)
        truth_table.append(row)
    return truth_table
