def evaluate_expression(assignments, expression):
    results = []
    for assignment in assignments:
        if len(assignment) != 2:
            continue
        p, q = assignment
        try:
            if expression == "P":
                results.append(p)
            elif expression == "Q":
                results.append(q)
            elif expression == "P < Q":
                results.append(p < q)
            elif expression == "P > Q":
                results.append(p > q)
            elif expression == "P == Q":
                results.append(p == q)
            elif expression == "P AND Q":
                results.append(p and q)
            elif expression == "P OR Q":
                results.append(p or q)
            elif expression == "NOT P":
                results.append(not p)
            else:
                pass
        except TypeError:
            pass
    return results
