    print(f"Expression '{expression4}': {results4}")

def evaluate_expression(assignments, expression):
    results = []
    for assignment in assignments:
        P = assignment[0]
        Q = assignment[1]
        try:
            scope = {'P': P, 'Q': Q}
            result = eval(expression, {}, scope)
            results.append(result)
        except Exception:
            results.append(None)
    return results
