        "test_case_1": {
            "expression": "A and (B or C)",
            "inputs": {"A": True, "B": False, "C": True},
            "expected": True,
            "actual": True
        },
        "test_case_2": {
            "expression": "not (A and B)",
            "inputs": {"A": True, "B": True},
            "expected": False,
            "actual": False
        },
