import re
def evaluate_expression(P, Q, expression):
    variables = {'P': P, 'Q': Q}
    def _eval(expr):
        expr = expr.strip()
        if not expr:
            return None
        if expr == 'P':
            return variables['P']
        elif expr == 'Q':
            return variables['Q']
        elif expr == 'AND':
            return variables['P'] and variables['Q']
        elif expr == 'OR':
            return variables['P'] or variables['Q']
        elif expr == 'NOT':
            return not variables['P']
        elif expr == '(':
            return _eval(expr[1:])
        elif expr == ')':
            return None
        else:
            try:
                result = eval(expr)
                if isinstance(result, bool):
                    return result
                return result
            except Exception:
                return None
    try:
        return _eval(expression)
    except Exception:
        return False
