import re
def evaluate_expression(P, Q, expression):
    variables = {'P': P, 'Q': Q}
    def _eval(expr, context):
        expr = expr.strip()
        if expr in context:
            return context[expr]
        if expr == 'True':
            return True
        if expr == 'False':
            return False
        if '(' in expr and expr.endswith(')'):
            balance = 0
            is_in_subexpr = True
            for i in range(len(expr) - 1):
                if expr[i] == '(':
                    balance += 1
                elif expr[i] == ')':
                    balance -= 1
                if balance == 0:
                    if i > 0 and expr[i-1] == '(':
                        sub_expr = expr[i:i+1]
                        result = _eval(sub_expr, context)
                        pass
            try:
                py_expr = expr.replace('AND', 'and').replace('OR', 'or').replace('NOT', 'not')
                for var, val in variables.items():
                    py_expr = py_expr.replace(var, str(val))
                return eval(py_expr)
            except Exception:
                return False                  
        if expr in variables:
            return variables[expr]
        if expr == 'True':
            return True
        if expr == 'False':
            return False
        raise ValueError(f"Unrecognized expression part: {expr}")
    try:
        return _eval(expression, variables)
    except Exception:
        return False
