class BooleanExpression:
    def __init__(self, expression):
        self.expression = expression
    def evaluate(self, variables):
        if not self.expression:
            return False
        tokens = self.expression.split()
        result = []
        for token in tokens:
            if token == 'AND':
                result.append('AND')
            elif token == 'OR':
                result.append('OR')
            elif token == 'NOT':
                if len(result) > 0:
                    result.append('NOT')
                else:
                    result.append('NOT')
            else:
                if token in variables:
                    result.append(variables[token])
                else:
                    raise ValueError(f"Undefined variable: {token}")
        return self._evaluate_tokens(result)
    def _evaluate_tokens(self, tokens):
        if not tokens:
            return False
        if len(tokens) == 1:
            if tokens[0] == 'True':
                return True
            if tokens[0] == 'False':
                return False
            raise ValueError("Invalid single token")
        if tokens[0] == 'NOT':
            operand = tokens[1]
            if operand == 'True':
                return False
            if operand == 'False':
                return True
            raise ValueError("Invalid operand after NOT")
        if tokens[0] == 'AND':
            left = self._evaluate_tokens(tokens[1:])
            right = self._evaluate_tokens(tokens[1:])
            return left and right
        if tokens[0] == 'OR':
            left = self._evaluate_tokens(tokens[1:])
            right = self._evaluate_tokens(tokens[1:])
            return left or right
        return False
