        if len(tokens_list) == 1:
            token = tokens_list[0]
            if token in values_map:
                return values_map[token], tokens_list[0]
            else:
                raise NameError(f"Undefined variable or value: {token}")
        if tokens_list[0] in (True, False):
            return tokens_list[0], tokens_list[0]
