    success = True
    try:
        if not numbers:
            success = False
        else:
            for num in numbers:
                if num < 0:
                    success = False
                    break
                if num % 2 != 0:
                    success = False
                    break
        if success:
            print("All numbers processed successfully.")
        else:
            print("Error: One or more conditions failed during processing.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
