class ListUtils:
    @staticmethod
    def get_intersection(list1, list2):
        set1 = set(list1)
        set2 = set(list2)
        if len(set1) < len(set2):
            smaller_set = set1
            larger_set = set2
        else:
            smaller_set = set2
            larger_set = set1
        intersection = set()
        for item in smaller_set:
            if item in larger_set:
                intersection.add(item)
        return list(intersection)
if __name__ == '__main__':
    list_a = [1, 2, 3, 4, 5]
