    numbers_as_strings = input_string.split()
    total_sum = 0.0
    for num_str in numbers_as_strings:
        try:
            number = float(num_str)
            total_sum += number
        except ValueError:
            print(f"Skipping invalid input: {num_str}")
    print(f"The total sum is: {total_sum}")

def calculate_sum_from_input(input_string):
    numbers = input_string.split()
    total_sum = 0.0
    for num_str in numbers:
        try:
            number = float(num_str)
            total_sum += number
        except ValueError:
            print(f"Skipping invalid input: {num_str}")
    return total_sum
if __name__ == '__main__':
    sample_input = "10 20.5 hello 30 4.5"
    result = calculate_sum_from_input(sample_input)
    print(f"The total sum is: {result}")

import unittest
class TestFindSmallest(unittest.TestCase):
    def find_smallest(self, data):
        if not data:
            raise ValueError("List cannot be empty")
        smallest = data[0]
        for item in data[1:]:
            if item < smallest:
                smallest = item
        return smallest
    def test_positive_integers(self):
        self.assertEqual(self.find_smallest([3, 1, 4, 1, 5]), 1)
        self.assertEqual(self.find_smallest([10, 5, 2, 8]), 2)
        self.assertEqual(self.find_smallest([5]), 5)
    def test_negative_numbers(self):
        self.assertEqual(self.find_smallest([-5, -1, -10, -3]), -10)
        self.assertEqual(self.find_smallest([-10, -5, -20]), -20)
        self.assertEqual(self.find_smallest([-1]), -1)
    def test_mixed_numbers(self):
        self.assertEqual(self.find_smallest([5, -2, 8, -1]), -2)
        self.assertEqual(self.find_smallest([10, 20, -5, 15]), -5)
        self.assertEqual(self.find_smallest([-10, 0, 5, -1]), -10)
    def test_duplicates(self):
        self.assertEqual(self.find_smallest([5, 5, 5, 5]), 5)
        self.assertEqual(self.find_smallest([10, 2, 10, 2]), 2)
        self.assertEqual(self.find_smallest([7, 7, 7, 7]), 7)
        self.assertEqual(self.find_smallest([1, 5, 1, 9]), 1)
    def test_single_element_list(self):
        self.assertEqual(self.find_smallest([42]), 42)
    def test_empty_list(self):
        with self.assertRaises(ValueError):
            self.find_smallest([])
if __name__ == '__main__':
    unittest.main(argv=['first-arg-is-ignored'], exit=False)

