def process_item_list(filename):
    item_dict = {}
    try:
        with open(filename, 'r') as file:
            item_names = file.readlines()
            for line in item_names:
                item = line.strip()
                if item:
                    item_dict[item] = True
    except FileNotFoundError:
        print(f"Error: File '{filename}' not found.")
    return item_dict
