    fruits1 = [("apple", "red"), ("banana", "yellow"), ("grape", "purple")]
    fruits2 = [("apple", "red"), ("orange", "orange"), ("grape", "green")]
    result = validate_and_merge_fruits(fruits1, fruits2)
    print(result)

