    manager = FavoriteColors()
    colors_to_add = [
        "Red",
        "blue",
        "red",
        "Green",
        "Blue",
        "purple"
    ]
    for color in colors_to_add:
        manager.add_color(color)
    counts = manager.get_color_counts()
    print(counts)

