def categorize_items(items, rule):
    categories = {}
    for item in items:
        category = None
        for cat, condition in rule.items():
            if condition(item):
                category = cat
                break
        if category is not None:
            if category not in categories:
                categories[category] = []
            categories[category].append(item)
        else:
            categories['uncategorized'] = categories.get('uncategorized', [])
            categories['uncategorized'].append(item)
    return categories
if __name__ == '__main__':
    sample_items = [
        "Apple",
        "Carrot",
        "Banana",
        "Broccoli",
        "Orange",
        "Potato",
        "Grape",
        "Spinach"
    ]
    categorization_rule = {
        "Vegetables": lambda x: x in ["Carrot", "Broccoli", "Potato", "Spinach"],
        "Fruits": lambda x: x in ["Apple", "Banana", "Orange", "Grape"]
    }
    result = categorize_items(sample_items, categorization_rule)
    print(result)

def categorize_items(items):
    categories = {
        "fruits": [],
        "vegetables": [],
        "dairy": [],
        "other": []
    }
    for item in items:
        if isinstance(item, str):
            lower_item = item.lower()
            if 'apple' in lower_item or 'banana' in lower_item or 'orange' in lower_item:
                categories["fruits"].append(item)
            elif 'carrot' in lower_item or 'broccoli' in lower_item or 'spinach' in lower_item:
                categories["vegetables"].append(item)
            elif 'milk' in lower_item or 'cheese' in lower_item:
                categories["dairy"].append(item)
            else:
                categories["other"].append(item)
        elif isinstance(item, dict):
            if item.get("type") == "fruit":
                categories["fruits"].append(item.get("name"))
            elif item.get("type") == "vegetable":
                categories["vegetables"].append(item.get("name"))
            elif item.get("type") == "dairy":
                categories["dairy"].append(item.get("name"))
            else:
                categories["other"].append(item.get("name"))
    return categories
if __name__ == '__main__':
    sample_data = [
        "Apple",
        "Carrot",
        "Milk",
        {"name": "Banana", "type": "fruit"},
        "Broccoli",
        "Cheese",
        "Steak",
        {"name": "Spinach", "type": "vegetable"},
        "Grape"
    ]
    result = categorize_items(sample_data)
    print("--- Categorization Results ---")
    print("Fruits:", result["fruits"])
    print("Vegetables:", result["vegetables"])
    print("Dairy:", result["dairy"])
    print("Other:", result["other"])

