import math
def bin_data(data, bins):
    if not bins:
        return []
    bin_edges = [data[0]]
    for i in range(1, len(data)):
        bin_edges.append(data[i])
    unique_edges = sorted(list(set(bin_edges)))
    if len(unique_edges) < 2:
        return []
    bins_result = []
    for i in range(len(unique_edges) - 1):
        lower_bound = unique_edges[i]
        upper_bound = unique_edges[i+1]
        if lower_bound < upper_bound:
            bin_start = lower_bound
            bin_end = upper_bound
            bin_data_list = []
            for x in data:
                if bin_start <= x < bin_end:
                    bin_data_list.append(x)
            if bin_data_list:
                bins_result.append({
                    "range": (bin_start, bin_end),
                    "data": bin_data_list
                })
    return bins_result
if __name__ == '__main__':
    sample_data = [1, 4, 2, 5, 8, 3, 7, 9, 10, 12]
    sample_bins = [2, 5, 8, 10]
    result = bin_data(sample_data, sample_bins)
    print(result)

import numpy as np
def bin_data(data, bins):
    if len(data) != len(bins) - 1:
        raise ValueError("The number of data points must be one less than the number of bin edges.")
    bins_edges = np.array(bins)
    labels = []
    for x in data:
        bin_index = np.searchsorted(bins_edges, x, side='right') - 1
        if 0 <= bin_index < len(bins_edges) - 1:
            labels.append(f"{bins_edges[bin_index]} to {bins_edges[bin_index + 1]}")
        else:
            labels.append("Out of bounds")
    return labels
if __name__ == '__main__':
    data_points = [1.2, 5.5, 10.1, 15.0, 22.3, 3.8, 8.9, 1.0, 18.5, 25.0]
    bin_boundaries = [0, 5, 10, 15, 20, 30]
    try:
        result = bin_data(data_points, bin_boundaries)
        for data, result_label in zip(data_points, result):
            print(f"Data point: {data}, Bin: {result_label}")
    except ValueError as e:
        print(f"Error: {e}")

import numpy as np
def bin_data(data, bins):
    if len(bins) < 2:
        return [data]
    bins = np.array(bins)
    if len(bins) != len(data) - 1:
        raise ValueError("Number of bins must be one less than the number of data points.")
    binned_data = []
    for i in range(len(data)):
        lower_bound = bins[i]
        upper_bound = bins[i+1]
        if lower_bound <= data[i] < upper_bound:
            binned_data.append(int(i))
        elif data[i] == upper_bound and i < len(bins) - 1:
            binned_data.append(int(i))
        else:
            binned_data.append(-1)
    return binned_data
if __name__ == '__main__':
    data_points = [1.2, 5.5, 10.1, 15.0, 22.3, 30.0, 35.5, 40.1]
    range_boundaries = [0, 10, 20, 30, 40, 50]
    try:
        result = bin_data(data_points, range_boundaries)
        print(result)
    except ValueError as e:
        print(f"Error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

