    inventory_data = {
        "apples": 10,
        "bananas": 15,
        "oranges": 8
    }
    price_data = {
        "apples": 0.50,
        "bananas": 0.30,
        "oranges": 0.60,
        "grapes": 2.50
    }
    total = calculate_inventory_value(inventory_data, price_data)
    print(total)

