    print(total)

def calculate_inventory_value(inventory, prices):
    total_value = 0
    for item, quantity in inventory.items():
        if item in prices:
            total_value += quantity * prices[item]
    return total_value
if __name__ == '__main__':
    inventory_data = {
        "apples": 10,
        "bananas": 5,
        "oranges": 8
    }
    price_data = {
        "apples": 0.50,
        "bananas": 0.30,
        "oranges": 0.60,
        "grapes": 2.50
    }
    total = calculate_inventory_value(inventory_data, price_data)
    print(total)

import unittest
class InventoryManager:
    def __init__(self):
        self.inventory = {}
    def add_item(self, item_name, quantity):
        if quantity <= 0:
            return
        if item_name in self.inventory:
            self.inventory[item_name] += quantity
        else:
            self.inventory[item_name] = quantity
    def get_item(self, item_name):
        return self.inventory.get(item_name, 0)
    def remove_item(self, item_name, quantity):
        if item_name not in self.inventory:
            return False
        if quantity <= 0:
            return False
        if self.inventory[item_name] >= quantity:
            self.inventory[item_name] -= quantity
            return True
        else:
            return False
class TestInventoryManager(unittest.TestCase):
    def setUp(self):
        self.manager = InventoryManager()
    def test_add_new_item(self):
        self.manager.add_item("Apples", 10)
        self.assertEqual(self.manager.get_item("Apples"), 10)
    def test_add_existing_item(self):
